# Сначала отдельно разбираем февраль: только там ответ зависит от года.
# Потом четыре месяца по 30 дней; во всех остальных месяцах 31 день.
m, y = map(int, input().split())
if m == 2:
    if (y % 4 == 0 and y % 100 != 0) or y % 400 == 0:
        print(29)
    else:
        print(28)
elif m == 4 or m == 6 or m == 9 or m == 11:
    print(30)
else:
    print(31)

# Перебираем все числа от a до b включительно – поэтому в range стоит b + 1.
# Число чётное, если остаток от деления на 2 равен нулю; для отрицательных это тоже верно.
a, b = map(int, input().split())
for x in range(a, b + 1):
    if x % 2 == 0:
        print(x, end=' ')

# Сначала проверяем самый строгий случай – делимость и на 3, и на 5.
# Если начать с проверки на 3, то для 15 программа ошибочно напечатает Fizz.
n = int(input())
for i in range(1, n + 1):
    if i % 3 == 0 and i % 5 == 0:
        print('FizzBuzz')
    elif i % 3 == 0:
        print('Fizz')
    elif i % 5 == 0:
        print('Buzz')
    else:
        print(i)

# Считаем баланс: +1 за открывающую скобку, -1 за закрывающую.
# Если баланс хоть раз стал отрицательным, закрывающей скобке не нашлось пары.
# В конце баланс должен быть равен нулю: все открытые скобки закрыты.
s = input().strip()
balance = 0
ok = True
for ch in s:
    if ch == '(':
        balance += 1
    else:
        balance -= 1
    if balance < 0:
        ok = False
if ok and balance == 0:
    print('YES')
else:
    print('NO')

# Перебираем все пары i < j двумя вложенными циклами: сначала по i, потом по j.
# В таком порядке первая найденная пара и есть нужный ответ.
# Флаг found помогает после break во внутреннем цикле выйти и из внешнего.
n, s = map(int, input().split())
a = list(map(int, input().split()))
found = False
for i in range(n):
    for j in range(i + 1, n):
        if a[i] + a[j] == s:
            print(i + 1, j + 1)
            found = True
            break
    if found:
        break
if not found:
    print(-1)

# Число b – среднее, если оно лежит между a и c (в любом порядке).
# То же проверяем для a; если не подошли ни b, ни a, то среднее – c.
# Нестрогие знаки <= важны: именно они правильно обрабатывают равные числа.
a, b, c = map(int, input().split())
if a <= b <= c or c <= b <= a:
    print(b)
elif b <= a <= c or c <= a <= b:
    print(a)
else:
    print(c)
